), new_results AS (
 INSERT INTO public.issuer_earnings_results(id,ticker,fiscal_period,company_name,filing_day,source_url,verification_status,verification_notes)
 SELECT s.id,s.ticker,s.fiscal_period,s.company_name,s.filing_day,s.source_url,'partial',s.notes FROM seed s
 WHERE NOT EXISTS(SELECT 1 FROM public.issuer_earnings_results r WHERE r.ticker=s.ticker AND (r.filing_day=s.filing_day OR r.fiscal_period=s.fiscal_period))
 ON CONFLICT DO NOTHING RETURNING id
